"""Render coordinator accounting from the final pinned decision/proposal bundles."""
import argparse
import collections
import datetime
import hashlib
import json
from pathlib import Path

OUT = Path("reports/all_unmatched_20261107/worker-07")


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def cell(value):
    return str(value).replace("|", "\\|").replace("\n", " ")


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--native-bundle", required=True)
    args = parser.parse_args()
    ds = json.loads((OUT / "decisions.json").read_text())["decisions"]
