    assert len(ds) == 188 and all(d["independent_review"]["status"] == "complete" for d in ds)
    native = Path(args.native_bundle)
    core_paths = [OUT / f"{name}.json" for name in ("decisions", "evidence", "proposals")] + [native / "review.yaml", native / "review.md"]
    facts = {"generated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(), "worker_slot": 7, "branch": "review/all-unmatched-w07-source-review-20261107", "base_commit": "e000d66dd26ab053e9b17ce7bf8d3c873c3dde99", "unmerged_dependency": "https://github.com/CultureBotAI/MediaIngredientMech/pull/1158", "frozen_shard_source": "/Users/marcin/Documents/VIMSS/ontology/Mechs/MediaIngredientMech/.temp/all-unmatched-20261107/queue/preliminary-v5/shards/shard-07.json", "frozen_shard_sha256": sha(OUT / "captures/root-shard07.json"), "source_root": "/Users/marcin/Documents/VIMSS/ontology/Mechs/MediaIngredientMech/.temp/all-unmatched-20261107/queue/preliminary-v5", "assigned_cases": len(ds), "independent_review_complete_cases": sum(d["independent_review"]["status"] == "complete" for d in ds), "sources": dict(collections.Counter(d["source"]["source"] for d in ds)), "dispositions": dict(collections.Counter(d["disposition"] for d in ds)), "proposal_kinds": dict(collections.Counter(p["kind"] for p in ps)), "proposal_count": len(ps), "evidence_count": len(es), "evidence_kinds": dict(collections.Counter(e["kind"] for e in es)), "existing_owners_compared": len({o["path"] for d in ds for o in d["owner_records"]}), "cross_shard_dependency_case_count": len(deps["dependencies"]), "core_artifacts": [{"path": str(path), "sha256": sha(path)} for path in core_paths], "native_review_bundle": str(native), "filed_findings": ["https://github.com/CultureBotAI/MediaIngredientMech/issues/1169", "https://github.com/CultureBotAI/MediaIngredientMech/issues/1170", "https://github.com/CultureBotAI/CultureMech/issues/672"], "existing_followups": ["https://github.com/CultureBotAI/CultureMech/issues/408", "https://github.com/CultureBotAI/MediaIngredientMech/issues/1157", "https://github.com/CultureBotAI/MediaIngredientMech/issues/702"], "maintained_sources_changed": False, "export_or_hold_approval": False, "remaining_scientific_decisions": [{"case_id": d["case_id"], "source_case_id": d["source"]["source_case_id"], "source_label": d["source"]["source_label"], "disposition": d["disposition"], "missing_requirement": d["missing_requirement"]} for d in ds if d["missing_requirement"]], "commit_receipt": "Final pushed commit and remote verification are recorded after commit in .temp/all-unmatched-worker-07/final-handoff.json and the session final message; no circular self-commit hash is invented in this artifact."}
    (OUT / "HANDOFF.json").write_text(json.dumps(facts, ensure_ascii=False, indent=2) + "\n")
    rows = ["# Worker07 source-review handoff", "", f"All {len(ds)} assigned cases have primary-source assessments and separate skeptical-review outcomes. The candidate set contains {len(ps)} isolated owner proposals: {facts['proposal_kinds'].get('edit_existing_owner', 0)} edits and {facts['proposal_kinds'].get('new_owner', 0)} new owners. No maintained source, mapping, unified snapshot, review selector or publication gate was changed.", "", "Use **decisions.json**, **evidence.json** and **proposals.json** as the final candidate manifest. `parts/`, preliminary receipts and unselected `proposed_owners/` files preserve the research and correction history; they are not additional active proposals.", "", "| Disposition | Cases |", "| --- | ---: |"]
    rows.extend(f"| {key} | {value} |" for key, value in facts["dispositions"].items())
    rows += ["", "The unresolved outcomes retain case-specific requirements after primary-source pursuit. Completion of review does not mean that every identity was resolved. Holds also remain within proposed cases, including eight of the seventeen sodium ammonium phosphate occurrences. [CASE-LEDGER.md](CASE-LEDGER.md) lists every source case and remaining requirement; `HANDOFF.json` provides exact paths and hashes.", "", "Primary and skeptical authorship is explicit in [subagent-scopes.json](subagent-scopes.json). A reviewed B's 70 cases, B reviewed C's 48, and C reviewed A's 70. The separate integration reviewer authored none of those decisions and reviewed the combined owners, shared Hutner formulation, four later root-authored stock decisions, final transformations and staged boundaries. Shared proposal cases reference both their applicability reviewer and their independent payload reviewer.", "", "Review corrected source attribution, formulation completeness, omitted source quantities and stock proposals. It also recovered the Sigma V6629 cyanocobalamin identity and the original Schaechter tetrahydrate formulation. The JCM900 and JCM979 Hutner subrecipes now share one nominal stock proposal; malformed molybdate wording remains unresolved. Candidate stock equivalence remains to be reconciled before minting all new owners; source IDs alone do not establish different chemistry. Exact groups are retained in captures/integration-nominal-stock-overlap-leads.json.", "", "The three filed findings are [dithionite/scutellarin aliases](https://github.com/CultureBotAI/MediaIngredientMech/issues/1169), [L/DL lactate alias](https://github.com/CultureBotAI/MediaIngredientMech/issues/1170), and [CultureMech phosphate/citrate ontology pointers](https://github.com/CultureBotAI/CultureMech/issues/672). The source-volume normalization defects are already tracked by [CultureMech #408](https://github.com/CultureBotAI/CultureMech/issues/408); calcium-pantothenate, cysteine/QSY9 and malate concerns retain their existing issue links.", "", f"The native owner comparison covers {facts['existing_owners_compared']} actual maintained owners with verdict `needs_curation`, five open identity-synonym findings, and explicit claim-scope exclusions. [Native YAML](../../../{native / 'review.yaml'}) and [rendered Markdown](../../../{native / 'review.md'}) were saved through the maintained helper. Source-only cases do not invent native owners. The earlier native observation is retained unchanged; this successor preserves its 77 targets and four open findings while adding the omitted malate-alias finding. These reports grant no role, whole-owner or export approval.", "", f"Validation: all {len(ps)} final payloads passed the native closed schema and full catalogue component-partonomy check; no new identifier collision or historical rewrite was introduced. All {validations['baseline_file_count']} baseline files retained their original hashes. Whole-shard structural integrity, auditor negative controls and native review validation/save/check logs are retained under `logs/`; structural PASS explicitly does not certify scientific truth. Earlier failed attempts remain visible with their later corrections.", "", f"[cross-shard-dependencies.json](cross-shard-dependencies.json) lists {len(deps['dependencies'])} other-shard cases referencing the same owners or exact labels, across worker slots {', '.join(map(str, sorted({h['worker_slot'] for h in deps['dependencies']})))}. These are dependency leads, not reviewed identities. In particular, NTA monohydrate source 1930 shares the source 1482 owner with worker 09; calcium pantothenate overlaps worker 06; dithionite and several hydrates overlap worker 08. Existing duplicate owner IDs are reported by the final proposal validator, not merged.", "", "The coordinator must retain original before-owner hashes, reconcile cross-shard and nominal-stock equivalence, and distinguish source-specific stock occurrences from the pure solute. Apply accepted proposals through guarded writers, withdraw inherited support for changed owner bytes, synchronize native surfaces and review every resulting published payload. PR1158 remains the explicit unmerged baseline dependency. This worker performs no merge, downstream rebuild or worker PR.", "", "The final pushed commit and remote-tip verification are supplied in the session handoff receipt after commit. The bundle SHA256 manifest covers the final retained artifacts without trying to hash itself."]
    (OUT / "HANDOFF.md").write_text("\n".join(rows) + "\n")
    ledger = ["# Worker07 complete case ledger", "", "Source strings and case IDs are unchanged. KG case occurrence arrays are empty by frozen-contract design; their original source records and helper-count semantics remain bound by case hashes. `decisions.json` contains the full reasoning, applicability, original occurrence IDs and independent-review references.", "", "| Index | Exact case ID | Source ID / label | Outcome | Active proposal IDs | Remaining requirement |", "| ---: | --- | --- | --- | --- | --- |"]
    for index, decision in enumerate(ds):
        ledger.append("| " + " | ".join(map(cell, [index, decision["case_id"], decision["source"]["source_case_id"] + " / " + decision["source"]["raw_source_label"], decision["disposition"], ", ".join(decision["proposal_ids"]) or "none", decision["missing_requirement"] or "No additional identity requirement identified in this scoped assessment; existing source/publication holds remain."])) + " |")
    (OUT / "CASE-LEDGER.md").write_text("\n".join(ledger) + "\n")
    print(json.dumps({k: facts[k] for k in ("assigned_cases", "proposal_count", "proposal_kinds", "existing_owners_compared", "cross_shard_dependency_case_count")}))


